-between;align-items:center}.small-label{color:#aa9ab2;font-size:9px;letter-spacing:.18em;font-weight:700}.name{font:500 22px/1.3 'Playfair Display',Georgia,serif;margin-top:3px}.age{display:inline-grid;place-items:center;vertical-align:3px;width:25px;height:17px;margin-left:4px;border:1px solid #ddbd7b55;border-radius:7px;color:#dfc58e;font:600 9px 'DM Sans',sans-serif;letter-spacing:.04em}.crown-icon{font-size:25px;color:#d3b17c;opacity:.8}.art-stage{height:375px;position:relative;overflow:hidden;margin:12px -7px 10px;border-radius:14px;background:radial-gradient(ellipse at 50% 43%,#8d6a784d,transparent 40%),linear-gradient(180deg,#30223a,#21192e 82%);display:flex;justify-content:center;align-items:flex-end}.art-stage:after{content:'';position:absolute;bottom:0;left:8%;right:8%;height:1px;background:linear-gradient(90deg,transparent,#d8bb8055,transparent)}.moon{position:absolute;width:100px;height:100px;right:17%;top:9%;border-radius:50%;background:#dfc996;opacity:.75;box-shadow:0 0 45px #f4dda555}.arch{position:absolute;width:240px;height:300px;top:17px;border:1px solid #bba17836;border-bottom:0;border-radius:140px 140px 0 0;box-shadow:inset 0 0 30px #d6bd8b08}.princess{position:absolute;bottom:-6px;height:352px;width:auto;z-index:2;filter:drop-shadow(0 13px 15px #100b1970);transition:transform .35s}.spark{position:absolute;z-index:3;color:#e6cf9b;text-shadow:0 0 12px #fff3c9;animation:twinkle 2.8s ease-in-out infinite}.s1{top:29%;left:18%;font-size:16px}.s2{top:53%;right:16%;font-size:18px;animation-delay:.9s}.s3{top:15%;left:29%;font-size:10px;animation-delay:1.6s}@keyframes twinkle{0%,100%{opacity:.35;transform:scale(.8)}50%{opacity:1;transform:scale(1.2)}}.stage-caption{position:absolute;z-index:4;bottom:13px;left:50%;transform:translateX(-50%);white-space:nowrap;display:flex;align-items:center;gap:8px;color:#dbc798;font-size:8px;font-weight:700;letter-spacing:.18em}.caption-dot{width:5px;height:5px;border-radius:50%;background:var(--gold);box-shadow:0 0 9px var(--gold)}.wardrobe-bar{margin-top:auto}.wardrobe-copy{display:flex;justify-content:space-between;color:#a89bb1;font-size:9px;letter-spacing:.16em;font-weight:700;margin-bottom:8px}.wardrobe-copy b{color:#e2c78e;letter-spacing:.06em}.progress{height:4px;background:#ffffff12;border-radius:9px;overflow:hidden}.progress i{display:block;width:0;height:100%;background:linear-gradient(90deg,#ba8d60,#f0d496);border-radius:9px;transition:width .5s ease;box-shadow:0 0 10px #e6bf77}.play-panel{padding:23px 26px 19px;display:flex;flex-direction:column;min-width:0}.round-line{display:flex;align-items:center;justify-content:space-between}.round-pill{border-radius:20px;border:1px solid #bd9a6655;padding:6px 11px;color:#e1c78f;font-size:9px;letter-spacing:.15em;font-weight:700;background:#e6c47b0b}.score-label{font-size:9px;color:#8f829b;letter-spacing:.14em}.score-row{display:flex;align-items:center;justify-content:center;gap:18px;margin:17px 0 18px}.score-card{text-align:center;width:92px}.score-name{font-size:9px;letter-spacing:.16em;color:#a99ab1;font-weight:700}.score-card strong{display:block;font:500 34px/1.15 'Playfair Display',Georgia,serif;color:#f2e3ca}.score-card.opponent strong{color:#e4a6ae}.score-card small{font-size:9px;color:#877a91}.score-vs{font:italic 11px 'Playfair Display',Georgia,serif;color:#806e8b}.duel-box{border:1px solid #e8d8c214;background:linear-gradient(135deg,#2a2238,#251d33);border-radius:14px;padding:12px 14px 11px;text-align:center;min-height:168px;display:flex;flex-direction:column;justify-content:center;transition:border-color .25s,background .25s}.hands{height:90px;display:flex;align-items:center;justify-content:center;gap:29px}.hand-slot{display:flex;flex-direction:column;align-items:center;gap:1px}.hand-icon{font-family:system-ui,sans-serif;font-size:42px;line-height:1;height:52px;display:grid;place-items:center;filter:drop-shadow(0 4px 8px #0004);transition:transform .2s}.hand-slot small{font-size:8px;letter-spacing:.16em;color:#a99bb1;font-weight:700}.duel-divider{color:#8e7c96;font-size:17px}.result{font:600 14px 'Playfair Display',Georgia,serif;min-height:19px;color:#ead6af}.quip{font-size:10px;color:#a99bb1;margin-top:4px;line-height:1.35}.duel-box.won{border-color:#b9a26855;background:linear-gradient(135deg,#30273a,#2c2432)}.duel-box.lost{border-color:#bf798344}.duel-box.tie{border-color:#a994bc44}.choose-label{text-align:center;font-size:9px;letter-spacing:.17em;font-weight:700;color:#a89bb1;margin:18px 0 10px}.choices{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.choice{position:relative;min-height:79px;border:1px solid #f0dfc219;border-radius:12px;background:#ffffff05;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;cursor:pointer;transition:transform .16s,border-color .2s,background .2s}.choice:hover{transform:translateY(-2px);border-color:#d6b87b99;background:#d2ad6510}.choice:active{transform:scale(.97)}.choice:focus-visible,.icon-btn:focus-visible,.reset-btn:focus-visible{outline:2px solid #f0d394;outline-offset:3px}.choice-icon{font-size:25px;line-height:1.15}.choice>span:nth-child(2){font-size:11px;color:#ded1c1}.choice kbd{position:absolute;right:7px;top:6px;color:#746a7e;font:9px 'DM Sans',sans-serif}.hint{min-height:25px;text-align:center;color:#81758d;font-size:9px;padding-top:10px}.bottom-row{display:flex;align-items:center;justify-content:space-between;margin-top:auto;padding-top:10px;border-top:1px solid #ffffff0d}.best{font-size:10px;color:#94879c}.best span{color:#d8b576;margin-right:5px}.best b{color:#dfcfb4;font-weight:600;margin-left:4px}.reset-btn{border:0;background:none;color:#bda78a;font-size:10px;cursor:pointer;padding:7px 5px;border-radius:6px}.reset-btn:hover{color:#f0d397;background:#ffffff08}footer{display:flex;justify-content:space-between;padding:15px 3px 0;color:#685d72;font-size:8px;font-weight:600;letter-spacing:.16em}.wardrobe{transition:opacity .35s}.wardrobe.w1,.wardrobe.w2,.wardrobe.w3{opacity:0}.princess.level-1 .w1,.princess.level-2 .w1,.princess.level-2 .w2,.princess.level-3 .w1,.princess.level-3 .w2,.princess.level-3 .w3{opacity:1}.princess.level-1{filter:drop-shadow(0 13px 15px #100b1970) hue-rotate(-6deg)}.princess.level-2{filter:drop-shadow(0 13px 15px #100b1970) hue-rotate(7deg)}.princess.level-3{filter:drop-shadow(0 13px 15px #100b1970) saturate(1.12)}.modal-backdrop{display:none;position:fixed;inset:0;z-index:20;background:#100b18c9;backdrop-filter:blur(7px);padding:20px;place-items:center}.modal-backdrop.open{display:grid}.modal{position:relative;width:min(430px,100%);background:linear-gradient(150deg,#30263b,#211a30);border:1px solid #e6ce9e35;border-radius:18px;padding:31px;box-shadow:var(--shadow)}.close-modal{position:absolute;right:15px;top:12px;border:0;background:none;color:#b7a9bd;font-size:25px;cursor:pointer}.modal h2{font:500 29px 'Playfair Display',Georgia,serif;margin:8px 0 16px}.modal p{color:#c1b4c6;font-size:13px;line-height:1.65}.modal b{color:#eed9a9}.modal-note{border-top:1px solid var(--line);padding-top:14px;color:#9e90a7;font-size:11px;margin-top:18px}.modal-ok{margin-top:20px;width:100%;border:1px solid #d8b87c66;border-radius:10px;background:#d9b56b18;color:#ecd5a2;padding:11px;cursor:pointer}.modal-ok:hover{background:#d9b56b2c}
@media(min-height:850px) and (min-width:701px){.shell{justify-content:center}.topbar{margin-bottom:5px}.intro{padding-top:15px;padding-bottom:24px}.game{min-height:555px}.portrait-panel{padding-top:24px}.art-stage{height:400px}.princess{height:375px}}
@media(max-width:760px){.shell{padding:12px 16px max(16px,env(safe-area-inset-bottom))}.topbar{height:40px}.intro{padding:10px 0 16px}h1{font-size:35px}.intro p{font-size:12px}.game{grid-template-columns:1fr;min-height:0}.portrait-panel{padding:15px 17px 13px;border-right:0;border-bottom:1px solid var(--line)}.portrait-head{padding:0 2px}.name{font-size:19px}.art-stage{height:270px;margin:8px -4px 9px}.princess{height:270px}.moon{width:68px;height:68px}.arch{height:240px;width:195px}.wardrobe-bar{margin-top:0}.play-panel{padding:15px 17px 14px}.score-row{margin:10px 0 13px}.score-card strong{font-size:29px}.duel-box{min-height:135px;padding:8px}.hands{height:72px}.hand-icon{font-size:37px;height:44px}.choose-label{margin:13px 0 8px}.choice{min-height:67px}.choice-icon{font-size:23px}.bottom-row{padding-top:8px}.hint{padding-top:7px;min-height:22px}footer{padding-top:12px;font-size:7px}}
@media(max-width:380px){.shell{padding-left:11px;padding-right:11px}.portrait-panel,.play-panel{padding-left:13px;padding-right:13px}.eyebrow{font-size:8px;letter-spacing:.2em}.game{border-radius:15px}.art-stage{height:240px}.princess{height:246px}.choice{min-height:62px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}

(() => {
  const $ = (id) => document.getElementById(id);
  const hands = { rock: '✊', paper: '✋', scissors: '✌' };
  const names = { rock: 'Rock', paper: 'Paper', scissors: 'Scissors' };
  const beats = { rock: 'scissors', paper: 'rock', scissors: 'paper' };
  const princessLines = {
    win: ['A clever move! You have my attention.', 'Nicely played. The night is young!', 'You caught me off guard—well done!'],
    loss: ['A royal victory! Shall we go again?', 'My move! You nearly had me.', 'A point for the crown. Your turn!'],
    tie: ['Great minds think alike. Again!', 'A tie! Fate wants another round.', 'We matched—let’s try once more.']
  };
  let player = 0, princess = 0, round = 1, level = 0, locked = false, soundOn = false;
  let best = Number(localStorage.getItem('moonlit-best') || 0);
  $('bestScore').textContent = best;

  function tone(freq, duration = .12) {
    if (!soundOn) return;
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = ctx.createOscillator(), gain = ctx.createGain();
      oscillator.type = 'sine'; oscillator.frequency.value = freq;
      gain.gain.setValueAtTime(.055, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + duration);
      oscillator.connect(gain); gain.connect(ctx.destination);
      oscillator.start(); oscillator.stop(ctx.currentTime + duration);
      oscillator.onended = () => ctx.close();
    } catch (_) { /* Audio is an optional enhancement. */ }
  }
  function updateScore() {
    $('playerScore').textContent = player;
    $('princessScore').textContent = princess;
    $('roundLabel').textContent = `ROUND ${round}`;
  }
  function choose(choice) {
    if (locked) return;
    const keys = Object.keys(hands), reply = keys[Math.floor(Math.random() * keys.length)];
    $('playerHand').textContent = hands[choice];
    $('princessHand').textContent = hands[reply];
    $('duelBox').classList.remove('won', 'lost', 'tie');
    $('playerHand').animate([{transform:'translateY(7px) scale(.8)'},{transform:'translateY(0) scale(1)'}], {duration:230, easing:'ease-out'});
    $('princessHand').animate([{transform:'translateY(-7px) scale(.8)'},{transform:'translateY(0) scale(1)'}], {duration:230, easing:'ease-out'});
    if (choice === reply) {
      $('duelBox').classList.add('tie');
      $('result').textContent = `It’s a tie — ${names[choice]}!`;
      $('quip').textContent = `“${princessLines.tie[Math.floor(Math.random() * 3)]}”`;
      $('hint').textContent = 'No point this time. Choose again!'; tone(430);
      return;
    }
    round++;
    const won = beats[choice] === reply;
    if (won) {
      player++; level = Math.min(3, level + 1);
      $('duelBox').classList.add('won');
      $('result').textContent = `${names[choice]} beats ${names[reply]} — you win!`;
      $('quip').textContent = `“${princessLines.win[Math.floor(Math.random() * 3)]}”`;
      $('hint').textContent = level < 3 ? 'A new royal look revealed!' : 'You’re one step closer to the crown!';
      $('princess').className.baseVal = `princess level-${level}`;
      $('wardrobeCount').textContent = `${level} / 3`;
      $('progressFill').style.width = `${level * 33.333}%`;
      $('outfitLabel').textContent = ['ROYAL BALL GOWN', 'VELVET EVENING LOOK', 'MIDNIGHT COURT ENSEMBLE', 'MOONLIT VICTORY LOOK'][level];
      tone(660, .15); setTimeout(() => tone(880, .18), 90);
    } else {
      princess++; $('duelBox').classList.add('lost');
      $('result').textContent = `${names[reply]} beats ${names[choice]} — Aurelia wins!`;
      $('quip').textContent = `“${princessLines.loss[Math.floor(Math.random() * 3)]}”`;
      $('hint').textContent = 'The princess takes this round. Keep going!'; tone(300, .18);
    }
    updateScore();
    if (player === 3 || princess === 3) finish(player === 3);
  }
  function finish(victory) {
    locked = true;
    document.querySelectorAll('.choice').forEach(button => button.disabled = true);
    $('roundLabel').textContent = 'MATCH COMPLETE';
    $('result').textContent = victory ? 'The moonlit match is yours!' : 'A royal victory for Aurelia!';
    $('quip').textContent = victory ? '“You’ve earned the crown—and a rematch, anytime.”' : '“A lovely match! The rematch is yours to call.”';
    $('hint').textContent = 'Start a new game to play again.';
    if (victory) {
      best++; localStorage.setItem('moonlit-best', best); $('bestScore').textContent = best;
      tone(740, .2); setTimeout(() => tone(990, .28), 160);
    }
  }
  document.querySelectorAll('.choice').forEach(button => button.addEventListener('click', () => choose(button.dataset.choice)));
  $('resetBtn').addEventListener('click', () => {
    player = 0; princess = 0; round = 1; level = 0; locked = false;
    document.querySelectorAll('.choice').forEach(button => button.disabled = false);
    $('duelBox').classList.remove('won', 'lost', 'tie');
    $('playerHand').textContent = $('princessHand').textContent = '✦';
    $('result').textContent = 'Choose your hand to begin';
    $('quip').textContent = '“A royal challenge! Show me what you’ve got.”';
    $('hint').textContent = 'Rock beats scissors · Paper beats rock · Scissors beat paper';
    $('princess').className.baseVal = 'princess';
    $('wardrobeCount').textContent = '0 / 3'; $('progressFill').style.width = '0%'; $('outfitLabel').textContent = 'ROYAL BALL GOWN';
    updateScore();
  });
  const modal = $('modal');
  function closeModal() { modal.classList.remove('open'); modal.setAttribute('aria-hidden', 'true'); }
  $('rulesBtn').addEventListener('click', () => { modal.classList.add('open'); modal.setAttribute('aria-hidden', 'false'); $('closeModal').focus(); });
  $('closeModal').addEventListener('click', closeModal); $('modalOk').addEventListener('click', closeModal);
  modal.addEventListener('click', event => { if (event.target === modal) closeModal(); });
  $('soundBtn').addEventListener('click', () => {
    soundOn = !soundOn; $('soundBtn').textContent = soundOn ? '♫' : '♩';
    $('soundBtn').setAttribute('aria-label', soundOn ? 'Turn sound off' : 'Turn sound on');
    $('soundBtn').title = soundOn ? 'Sound on' : 'Sound off'; if (soundOn) tone(660);
  });
  document.addEventListener('keydown', event => {
    if (modal.classList.contains('open')) { if (event.key === 'Escape') closeModal(); return; }
    if (event.target.closest('button')) return;
    if (event.key === '1') choose('rock'); if (event.key === '2') choose('paper'); if (event.key === '3') choose('scissors');
  });
})();

