  const tieScore = await page.locator('#playerScore').textContent();
  await page.evaluate(() => { Math.random = () => 0.999; });
  for (let i = 0; i < 3; i++) await page.keyboard.press('1');
  const finalLabel = await page.locator('#scoreLabel').textContent();
  const finalText = await page.locator('#result').textContent();
  const finalScore = [await page.locator('#playerScore').textContent(), await page.locator('#princessScore').textContent()];
  const disabledAtFinish = await page.locator('.choice').first().isDisabled();
  await page.locator('#rulesBtn').click();
  await page.keyboard.press('2');
  const modalKeepsScore = (await page.locator('#playerScore').textContent()) === '3';
  await page.keyboard.press('Escape');
  const modalClosed = !(await page.locator('#modal').getAttribute('class')).includes('open');
  await page.locator('#resetBtn').click();
  const reset = {
    score: [await page.locator('#playerScore').textContent(), await page.locator('#princessScore').textContent()],
    label: await page.locator('#scoreLabel').textContent(),
    enabled: !(await page.locator('.choice').first().isDisabled()),
    wardrobe: await page.locator('#wardrobeCount').textContent()
  };
  await page.screenshot({ path: 'screenshots/latest.jpg', type: 'jpeg', quality: 78, fullPage: true });
  console.log(JSON.stringify({ tie, tieScore, finalLabel, finalText, finalScore, disabledAtFinish, modalKeepsScore, modalClosed, reset, errors }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
